const NUMBER_OF_PARTICLES = 2000

const X_GRID = 16
const Y_GRID = 16

function setup() {
	const width = windowWidth;
	const height = windowHeight;
	createCanvas(windowWidth, windowHeight);
	background(0);
	fill(255)
	stroke(255);
	strokeWeight(1);
	frameRate(30)

	const gridWidth = width / X_GRID
	const gridHeight = height / Y_GRID

	particles = []
	const batchingFactor = 1
	const particlesPerSection = NUMBER_OF_PARTICLES / (X_GRID * Y_GRID);

	for (let xIdx = 0; xIdx < X_GRID; xIdx++) {
		const gridParticles = []
		for (let yIdx = 0; yIdx < Y_GRID; yIdx++) {


			for (let i = 0; i < particlesPerSection; i++) {

				const minBound = createVector(xIdx * gridWidth, yIdx * gridHeight);
				const maxBound = createVector((xIdx + 1) * gridWidth, (yIdx + 1) * gridHeight);

				const x = random(gridWidth) + minBound.x
				const y = random(gridHeight) + minBound.y

				const particle = new Particle(x, y, [minBound, maxBound])
				gridParticles.push(particle);
			}
		}
		particles.push(gridParticles)
	}


}

function draw() {
	particles.forEach(particleGroup => {
		particleGroup.forEach(particle => {
			particle.update();
			particle.draw();
			// stroke(random(100))//random(180), random(180), random(180))
		})
	})
}

// === Tab: Particle ===
DV_FACTOR = 4

class Particle {

	constructor(x, y, bounds) {
		this.x = x
		this.y = y
		this.pos = createVector(x, y);
		this.v = createVector(0, 0);
		this.bounds = bounds
	}

	correctBounds (newPosition, bounds) {
		// Max Bounds
		if (newPosition.x > bounds[1].x) { 
			newPosition.x = bounds[1].x + (bounds[1].x - newPosition.x);
			this.v.x = this.v.x * -1
		}

		if (newPosition.y > bounds[1].y) {
			newPosition.y = bounds[1].y + (bounds[1].y - newPosition.y)
			this.v.y = this.v.y * -1
		}

		// Min Bounds
		if (newPosition.x <= bounds[0].x) {
			newPosition.x = bounds[0].x + (bounds[0].x - newPosition.x)
			this.v.x = this.v.x * -1;
		}

		if (newPosition.y <= bounds[0].y) {
			newPosition.y = bounds[0].y + (bounds[0].y - newPosition.y)
			this.v.y = this.v.y * -1;
		}

		this.pos = newPosition;
	}

	update() {
		// Update velocity vector
		let dv = createVector((noise(this.pos.x/width) * 2 - 1) * DV_FACTOR, (noise(this.pos.y/height) * 2 - 1) * DV_FACTOR);
		this.v = dv;

		// Update position
		let newPosition = this.pos.add(this.v)

		// Correct bounds	positioning and vectors
		this.correctBounds(newPosition, this.bounds)

	}

	draw() {
		// if ((this.pos.y > windowHeight/2) && (this.pos.x > windowWidth/2)) stroke(0)
		// else if ((this.pos.y > windowHeight / 2) && (this.pos.x < windowWidth / 2)) stroke(255)
		// else if ((this.pos.y < windowHeight / 2) && (this.pos.x < windowWidth / 2)) stroke(0)
		// else if ((this.pos.y < windowHeight / 2) && (this.pos.x > windowWidth / 2)) stroke(255)
		// else stroke(255, 0, 0)
		stroke(255,255,255, 20)
		strokeWeight(1)
		point(this.pos.x, this.pos.y);
		if (frameCount < 0) {
			stroke(255,255,255,4)
			strokeWeight(8)
		} else {
			let r = noise(this.pos.x/width, this.pos.y/height) * 200 + 55
			let g = noise(this.pos.y/height) * 200 + 55
			let b = noise(this.pos.y/height) * 200 + 55
			// stroke(r, g, b, 10)
			stroke(255,255,255,10)
			strokeWeight(4);
		}
		point(this.pos.x, this.pos.y);
	}

}

class CircularBoundParticle extends Particle {
	correctBounds(newPosition, bounds) {
		const center = createVector(this.x, this.y)
		const distanceToCenter = Math.sqrt((newPosition.x - center.x) ** 2 + (newPosition.y - center.y) ** 2);

		// bounds is radius of circle
		if (distanceToCenter > bounds) {
			// get angle of collision

			// get position relative to center
			let positionCenter = createVector(this.pos.x - center.x, this.pos.y - center.y)
			let positionNorm = p5.Vector.normalize(positionCenter);
			let vNorm = p5.Vector.normalize(this.v);

			let rebound = p5.Vector.dot(positionNorm, this.v);
			// rebound = p5.Vector.normalize(rebound)
			let reflected = p5.Vector.sub(this.v, p5.Vector.mult(positionNorm, rebound * 2))

			this.v = reflected;
			let overshoot = newPosition - (center + bounds)
			let overshootMagnitude = p5.Vector.mag(overshoot)
			this.pos.sub(overshoot);
			this.pos.add(p5.Vector.normalize(this.v) * overshootMagnitude)		
		}
	}
}

